CREATE TABLE IF NOT EXISTS customer_sites (id INTEGER PRIMARY KEY AUTOINCREMENT, project_key TEXT NOT NULL, match_key TEXT NOT NULL, address TEXT NOT NULL, label TEXT, source TEXT NOT NULL, edited INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0, seen_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_customer_sites_match ON customer_sites(project_key, match_key);
CREATE TABLE IF NOT EXISTS customer_contacts (id INTEGER PRIMARY KEY AUTOINCREMENT, project_key TEXT NOT NULL, match_key TEXT NOT NULL, name TEXT, phone TEXT, email TEXT, job_title TEXT, site_id INTEGER, is_primary INTEGER NOT NULL DEFAULT 0, source TEXT NOT NULL, edited INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0, seen_contract INTEGER NOT NULL DEFAULT 0, seen_open INTEGER NOT NULL DEFAULT 0, seen_at TEXT, items TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_customer_contacts_match ON customer_contacts(project_key, match_key);
